#!/usr/bin/env python3
"""mkbody.py (13.11.2026, queue-ar/dsmain/zzzaql) -- writes zzzaql/dsm-zzzaql.sh from ref14/dsm-ref14.sh (74981d12, the int14
reference read: its start, pin, read-back, tables and harness code) by ASSERTED replacements (each must match exactly the stated
number of times); the original is not changed. Usage: python3 -I mkbody.py ../ref14/dsm-ref14.sh dsm-zzzaql.sh"""
import hashlib, sys

src, dst = sys.argv[1], sys.argv[2]
s = open(src).read()
md5 = hashlib.md5(s.encode()).hexdigest()[:8]
assert md5 == "74981d12", "ref14/dsm-ref14.sh is not 74981d12 (got %s)" % md5


def rep(old, new, n=1):
    global s
    c = s.count(old)
    assert c == n, "expected %d x %r, found %d" % (n, old[:120], c)
    s = s.replace(old, new)


HEADER = r'''#!/bin/bash
# dsm-zzzaql.sh (13.11.2026, queue-ar/dsmain/zzzaql, a builder for ds-main-port) -- NOT a queue item; the body of
# 57-p4zyzzzzz-ds-r92zzzzzz-ref12zzzzzz-zzzaql.sh. Log tag "RESULT xzaql ", out runs/xdsm/zzzaql (ZQA_OUT). A COPY of
# ref14/dsm-ref14.sh (74981d12, the int14 reference read as staged 12.11. and run 22:18-22:40; tag xref14 -> xzaql, knobs R14_ -> ZQA_;
# generated by zzzaql/mkbody.py, every edit an asserted replacement; the original not changed; unused functions kept): the SAME start
# words, guards, image checks, tables (ref14/m16-forms.txt, ref14/a11-entries.txt, not re-benched), n-gram reuse (ngshare), THE int14
# PIN (arm O, read back on fn4 and on every rank) and the same c8 harness (harness/ncmb3.py, the fixed prompt set reset per block) --
# + RADIANCE_AQL_STAMP=1 at the start (ref14's STAMPN knob, 0 there; stack2's yaml passes AQLSTAMP -> RADIANCE_AQL_STAMP and
# RADIANCE_AQL_STAMP_OUT=/stats/stamps.csv) + zzzaql/aqlcp.py (the analyser).
# THE AQL-STAMPED c8 CRITICAL-PATH READ (coordinator 13.11.: the last open question on the exact c8 list -- how much of int14's real c8
# decode step (~34.6 ms unprofiled at ~8 rows) is IDLE on the critical path: dependent-launch gaps, lane waits, host / CPU time,
# all-reduce waits; prof2's --profile-ops numbers (c8 44.82 ms a step, lane waits 4.46, host remainder 1.76; per-row fit intercept 20 ms,
# lane 4.10 / host 1.46) are PROFILED: --profile-ops plays no recorded pass and K1's calibration says profiled small-op time overstates
# the real saving). METHOD = the ha-k1prof / hy-z0prof stamps (LEVERS K1, Z0, 1U-HG): RADIANCE_AQL_STAMP=1 gives every dispatch of
# every pass played on CARD 0 a completion signal with its start / end (nothing else changes: the barrier bits and the chain are the
# unstamped ones); stamping costs ~7-8 % at c1 (ha-k1prof 17.0 vs 15.8 ms), so the stamped step is compared with the unstamped twin.
# ONE FRESH START, stamped (ngshare, no ATTACH, MAXSEQS 16, compose guard in the item), image radiance-local:ds41-int14c-678c176f-
# 579d0bc2-l (a7ca6bcdf07b), THE int14 PIN exactly (ref14's arm O = yzint14c's Z), read back on fn4 and every rank.
# READINGS: the warm-up answers vs stock (identw; a difference STOPS before the c8 blocks: stamping changes no computation), then
#   ZQA_C8N (2) c8 blocks under O on the fixed harness (ncmb3 1x8, schedule S, 35 s window after 10 s warm, T 0, ignore_eos, the fixed
#   prompt set reset per block = ref14's c8-k-S-O blocks exactly), each bracketed by clock pairs (UTC + CLOCK_MONOTONIC from one
#   process: the stamps' clock) -> ~750 decode steps a block stamped.
# SUMMARY (after the container is down: the stamp writer flushes at exit): p12win.py split per block (the STAMPED step-log decode ms),
#   ncmatch c8t (the newcomer steps, INFO), /stats experts.ranks per rank (misses / stream a decode step, INFO), then aqlcp.py stamps
#   over the blocks' windows: per decode step (one trunk pass start to the next) wall, GPU busy on the critical path and the IDLE on
#   card 0's critical path by class -- dependent-launch gaps / lane (cross-queue) waits / host (play boundaries = the pass's host ops +
#   between passes) / AR wait (collectives above their transfer floor) / other (single stalls >= 1 ms); steady steps and the 10 decode
#   steps right after a newcomer kept separate; where the idle sits (kernel pairs); card 0's share of last arrivals at the collectives.
#   aqlcp.py summary: "AQL c8: wall X ms a decode step, critical-path idle Y ms (Z %) = launch gaps .. / lane waits .. / host .. / AR wait
#   .. / other ..", the stamped step-log ms vs the UNSTAMPED TWIN = ref14's c8-1-S-O / c8-2-S-O split (same image, pin, harness, MAXSEQS;
#   cross-start: stamping is a start-time switch, aql.cpp reads RADIANCE_AQL_STAMP once), prof2 as INFO, and the verdict "launch / sync
#   levers worth >= 1 ms: YES / NO" on launch + lane + host after removing the WHOLE stamping cost from the launch gaps (conservative).
# PER RANK: the stamps are CARD 0's only (aql.cpp StampRun::begin skips a tape whose first stream is not ordinal 0; no build here) --
#   ranks 1-3 are read through card 0's AR wait (how far the slowest peer runs behind) and its last-arrival share, + /stats per rank.
# The refusal probes (swnote) post exl3_x3d 2 expecting HTTP 400: still right on int14 (lever K25U's exl3_x3d 2..4 is NOT in this image).
# ~12-14 min (start ~5.5 with the n-gram fill, checks ~1, two c8 blocks ~2, summary ~3: ~10-15 M stamp rows, aqlcp.py ~1 min, gzip);
#   BUDGET ZQA_BUDGET_MIN 16 for the sections, <= 20 with the summary. NO evict, no cc_sim, no power / host / fan settings; production
#   compose files read only; nothing profiled. The stamp dump (~1-2 GB raw) is gzipped once summarised (raw dropped); disk guard 12 GB.
# MOCK: ZQA_SW=0 = a server without the int9b .. int14c switches (queue-ar/tools/mockrad): the pin posts none of them; the mock server
#   writes no stamps, so aqlcp.py synth writes SYNTHETIC stamps over the mock's windows (logged as MOCK, never on a real run) and every
#   parser runs. DRYRUN=1 bash dsm-zzzaql.sh : prints every command; checks the image literals, every helper (+ selftests, aqlcp.py's),
#   the two tables' md5s, the ngramshare files, both yamls, the sidecars, the twin's files, the disk; no server, no GPU.
'''
head, sep, rest = s.partition("\nset -u\n")
assert sep and head.startswith("#!/bin/bash\n# dsm-ref14.sh"), "header split"
s = HEADER.rstrip("\n") + sep + rest

# the tables and ref14's own helpers stay in ref14/ (this body lives in zzzaql/)
rep("YDS=$HD/r14sum.py; NCM=$HD/ncmatch.py;", "YDS=$HD/../ref14/r14sum.py; NCM=$HD/../ref14/ncmatch.py;")
rep("A4TAB=$HD/m16-forms.txt;", "A4TAB=$HD/../ref14/m16-forms.txt;")
rep("A11TAB=$HD/a11-entries.txt;", "A11TAB=$HD/../ref14/a11-entries.txt;")
# tag, knobs, item, out
n_tag = s.count("xref14")
s = s.replace("xref14", "xzaql")
n_k = s.count("R14_")
s = s.replace("R14_", "ZQA_")
assert n_tag > 50 and n_k > 100, (n_tag, n_k)
rep("ITEM=${ZQA_ITEM:-57-p4zyzzzzz-ds-r92zzzzzz-ref12zzzzzz-zref14}", "ITEM=${ZQA_ITEM:-57-p4zyzzzzz-ds-r92zzzzzz-ref12zzzzzz-zzzaql}")
rep("O=${ZQA_OUT:-$R/xdsm/ref14}", "O=${ZQA_OUT:-$R/xdsm/zzzaql}")
# stamping on (ref14's knob, 0 there); disk 12 GB (the stamp dump); budget 16 min for the sections
rep("ARCV=0; DOID=0; STAMPN=0", "ARCV=0; DOID=0; STAMPN=${ZQA_STAMP:-1}")
rep("DISKMIN=${ZQA_DISKMIN_MB:-11000}; BUDGET=${ZQA_BUDGET_MIN:-35};", "DISKMIN=${ZQA_DISKMIN_MB:-12000}; BUDGET=${ZQA_BUDGET_MIN:-16};")
rep('DESC="THE int14 REFERENCE READ (ref14: image int14c,', 'DESC="THE AQL-STAMPED c8 CRITICAL-PATH READ on THE int14 BASE (zzzaql, RADIANCE_AQL_STAMP=$STAMPN; ref14\'s start and pin: image int14c,')
# aqlcp.py + the knobs of this item (after the helper paths)
rep("C8GN=${ZQA_C8GN:-2};", "NC=${ZQA_NC:-10}; MINST=${ZQA_MIN_STEPS:-200}; C8GN=${ZQA_C8GN:-2};")   # zzzaql: the post-newcomer steps kept apart; the fewest stamped decode steps that are not a VIRHE
rep("U1S=$HD/../1u/u1sum.py ", "AQL=$HD/aqlcp.py   # this item's analyser\n"
    "TWINS=${ZQA_TWINS-$R/xdsm/ref14/split-c8-1-S-O.txt $R/xdsm/ref14/split-c8-2-S-O.txt}   # the UNSTAMPED twin: ref14's c8 35 s blocks (same image, pin O, harness S, MAXSEQS 16; p12win split)\n"
    "PROF2=${ZQA_PROF2:-prof2 (xp2 12.11., int12, MAXSEQS 16, --profile-ops) c8 rank 0: wall 44.82 ms a decode step, lane waits 4.46 (stager 0.41), host remainder 1.76 (ranks 1-3: lane 4.47-4.59, host 1.74-1.75); P12FIT intercept 20.04 ms at 0 rows, lane waits 4.10, host remainder 1.46}\n"
    "U1S=$HD/../1u/u1sum.py ")
rep("for v in $C8GN $C8N $C16N $C4N $C1N $SWN; do", "for v in $C8GN $C8N $C16N $C4N $C1N $SWN $NC $MINST; do")
rep('[ $C8GN -ge 1 ] || { echo "ZQA_C8GN >= 1"; exit 1; }',
    '[ $C8GN -ge 1 ] || { echo "ZQA_C8GN >= 1"; exit 1; }; [ $C8N -ge 1 ] && [ $C8N -le 4 ] || { echo "ZQA_C8N 1..4 (the stamped c8 blocks)"; exit 1; }; [ $NC -ge 1 ] && [ $NC -le 50 ] || { echo "ZQA_NC 1..50"; exit 1; }')

# dstart: the start line, the readings line, the readings
rep('xlog "$tag: start (REFERENCE; ngshare:', 'xlog "$tag: start (STAMPED: RADIANCE_AQL_STAMP=${AQLSTAMP:-unset}, every played pass on card 0 -- NOT a speed; ngshare:')
rep('''  xlog "THE int14 PIN O (read back, fn4 + every rank): $(pinj O | cut -c1-1300) | B (c8 work-based set only) = $(armj B) | readings: 1 identity warm-up, a1 vs yzint14c a1-Z + ref12 a1, gs$GSC, A11 in range [$A11ID], staggered (ANY failure: STOP) | 2 1u essay 1 + $U1N, switched x$SWN | 3 c8 work-based (gens $C8GN) [$C8GORD], c8 35 s x$C8N (INFO), c16 fixed x$C16N, c16 CAP48 | 4 cold [$CDEPTHS] | 5 c4 (warm-up $C4WARMUP) x$C4N, c1 x$C1N"
  stopfile || r14reads''',
    '''  xlog "THE int14 PIN O (read back, fn4 + every rank): $(pinj O | cut -c1-1300) | readings: the warm-up identity (a difference STOPS), then $C8N STAMPED c8 blocks under O (ncmb3 fixed 1x8, schedule S, $C8WARM s warm + $C8WIN s window, T 0, the fixed prompt set reset per block = ref14's c8-k-S-O), each bracketed by clock pairs | summary: split per block, ncmatch c8t, /stats per rank, aqlcp.py stamps (nc $NC) + summary vs the unstamped twin (ref14)"
  stopfile || zqreads''')

NEWFUNCS = r'''# ---------------------------------------------------------------- zzzaql's own functions (the stamped c8 blocks, the summary)
clockpair() {   # clockpair: "UTC_S MONO_NS" from ONE process (the harness marks' clock and the stamps' clock, read together)
  [ "$DRY" = 1 ] && { echo "0 0"; return 0; }
  python3 -c 'import time; print("%.6f %d" % (time.time(), time.clock_gettime_ns(time.CLOCK_MONOTONIC)))'
}
zqreads() {   # the readings (module header): the warm-up identity gate, then C8N stamped c8 blocks under O, each bracketed by clock pairs
  local k nm
  idok n5   # the warm-up answers vs stock (identw at the start; no line = not compared = the stop)
  stopfile && return 0
  if [ -n "$IDFAIL" ]; then
    STOPPED=1
    xlog "IDENTITY GATE: VIRHE the warm-up answers are not IDENTICAL to stock [$(echo $IDFAIL)] -> the item STOPS before the stamped c8 blocks (stamping changes no computation: NEEDS USER)"
    return 0
  fi
  xlog "IDENTITY GATE: the warm-up answers IDENTICAL to stock -> the stamped c8 blocks run"
  for k in $(seq 1 $C8N); do
    stopfile && return 0
    budok "stamped c8 block $k" 2 || continue
    nm=c8-$k-S-O
    if [ "$DRY" = 1 ]; then echo "+ clockpair >> $O/clock-$nm.txt (before and after the block)"; else clockpair >> $O/clock-$nm.txt; fi
    mbx 8 $k O S || true
    [ "$DRY" = 1 ] || clockpair >> $O/clock-$nm.txt
  done
  return 0
}
zqsummary() {   # p12win.py split per stamped block (the stamped step-log decode ms), ncmatch c8t (INFO), /stats per rank, aqlcp.py stamps + summary
  local EL=$O/xzaql-n5-engine-full.log.gz ST=$STATSDIR/stamps.csv nm f w l wins="" spl="" twn=""
  if [ "$DRY" = 1 ]; then
    echo "+ per stamped block c8-<k>-S-O: python3 -I -B $R12S split $EL --win <name>:<marks> --mbline $O/c8/<name>.txt --sw0/--sw1 ... > $O/split-<name>.txt (the STAMPED step-log decode ms a step)"
    echo "+ python3 -I -B $NCM $EL --set c8t --block c8-<k>-S-O:O:$O/c8/c8-<k>-S-O-reqs.jsonl ... --min 4 --json $O/ncm-c8t.json (the newcomer steps, INFO)"
    echo "+ python3 -I -B $AQL ranks c8-<k>-S-O $O/st-c8-<k>-S-O-0.json $O/st-c8-<k>-S-O-1.json >> $O/ranks.txt (per rank misses / stream a decode step, INFO)"
    echo "+ python3 -I -B $AQL monowin $O/c8/c8-<k>-S-O-reqs.jsonl $O/clock-c8-<k>-S-O.txt -> the block's window on the monotonic clock"
    echo "+ ($([ $SW = 0 ] && echo "MOCK: no stamps from the mock server -> python3 -I -B $AQL synth --out $ST --win ... (SYNTHETIC, logged); " || echo "real run: "))timeout 1200 nice -n 10 python3 -I -B $AQL stamps $ST --win c8-1-S-O:<m0>:<m1> .. --nc $NC --json $O/aql.json --label c8 > $O/aql-stamps.txt"
    echo "+ python3 -I -B $AQL summary --stamps $O/aql.json --split c8-<k>-S-O=$O/split-c8-<k>-S-O.txt .. --twin ref14-<..>=<f> for f in [$TWINS] --ranks $O/ranks.txt --ncm $O/ncm-c8t.txt --prof2 '<prof2 INFO>' --min-steps $MINST --label c8 -> RESULT xzaql AQL lines (the summary line, post-newcomer, per rank, where, verdict)"
    echo "+ twin files: $(for f in $TWINS; do [ -s $f ] && echo -n "$(basename $f) present ($(grep -o '[0-9.]* ms a step' $f | head -1)) " || echo -n "$(basename $f) MISSING "; done)"
    echo "+ gzip -1 $ST (raw dropped once summarised); tar -czf $O/raw-snaps.tar.gz (st-*.json fn-*.json m-*.txt c8/*-samp.jsonl c8/*-st-w*.json) and remove them; gzip start logs"
    return 0
  fi
  if [ -s $EL ]; then
    for f in $(ls $O/c8/c8-*-S-O-reqs.jsonl 2>/dev/null); do
      nm=$(basename $f -reqs.jsonl)
      splitblk $EL $nm || continue
      while IFS= read -r l; do xlog "$nm (STAMPED) ${l:0:1600}"; done < <(grep -hE '^P12SPLIT' $O/split-$nm.txt 2>/dev/null)
      spl="$spl --split $nm=$O/split-$nm.txt"
    done
    ncmset $EL c8t 4 $(ls $O/c8/c8-*-S-O-reqs.jsonl 2>/dev/null)
    l=$(zcat $EL 2>/dev/null | grep -m1 'RADIANCE_AQL_STAMP times every dispatch' | sed 's/^[^ ]*Z //' | cut -c1-220)
    xlog "stamps (engine log): ${l:-no 'RADIANCE_AQL_STAMP times every dispatch' line}$([ -z "$l" ] && [ $SW = 1 ] && [ $STAMPN -gt 0 ] && echo " -- VIRHE stamping not confirmed by the engine") | passes stamped in part ('signals are in flight' lines): $(zcat $EL 2>/dev/null | grep -c 'RADIANCE_AQL_STAMP: .* signals are in flight')"
  else xlog "summary: NOTE no engine log $EL (the start did not come up): no step-log split"; fi
  : > $O/ranks.txt
  for f in $(ls $O/c8/c8-*-S-O-reqs.jsonl 2>/dev/null); do
    nm=$(basename $f -reqs.jsonl)
    timeout 60 python3 -I -B $AQL ranks $nm $O/st-$nm-0.json $O/st-$nm-1.json >> $O/ranks.txt 2>&1
  done
  for f in $(ls $O/c8/c8-*-S-O-reqs.jsonl 2>/dev/null); do
    nm=$(basename $f -reqs.jsonl)
    if w=$(timeout 60 python3 -I -B $AQL monowin $f $O/clock-$nm.txt 2>> $O/aql-err.txt) && [ -n "$w" ]; then wins="$wins --win $nm:$w"
    else xlog "summary: VIRHE no monotonic window for $nm ($(tail -1 $O/aql-err.txt 2>/dev/null | cut -c1-200))"; fi
  done
  if [ $SW = 0 ] && [ ! -s $ST ] && [ ! -s $ST.gz ] && [ -n "$wins" ]; then
    timeout 300 python3 -I -B $AQL synth --out $ST $wins > /dev/null 2>> $O/aql-err.txt \
      && xlog "MOCK (ZQA_SW=0): the mock server writes no stamps -- aqlcp.py synth wrote SYNTHETIC stamps over the windows (NOT a reading)"
  fi
  [ -s $ST ] || { [ -s $ST.gz ] && ST=$ST.gz; }
  if [ -s $ST ] && [ -n "$wins" ]; then
    xlog "stamps: $(du -m $ST | cut -f1) MB ($(basename $ST)); windows$(echo $wins | sed 's/--win / /g') (monotonic ns); aqlcp.py stamps (nice 10) ..."
    timeout 1200 nice -n 10 python3 -I -B $AQL stamps $ST $wins --nc $NC --json $O/aql.json --label c8 > $O/aql-stamps.txt 2>&1
    while IFS= read -r l; do xlog "${l:0:2400}"; done < <(grep -h '^AQLCP ' $O/aql-stamps.txt 2>/dev/null | grep -v '^AQLCP {')
  else xlog "summary: VIRHE no stamps file ($STATSDIR: $(ls -la $STATSDIR 2>&1 | tail -3 | tr '\n' ' ' | cut -c1-240)) or no window -- nothing priced"; fi
  for f in $TWINS; do [ -s $f ] && twn="$twn --twin ref14-$(basename $f .txt | sed 's/^split-//')=$f"; done
  [ -n "$twn" ] || xlog "summary: NOTE the unstamped twin's split files [$TWINS] are missing -- the verdict uses the stamped figure (an upper bound)"
  timeout 300 python3 -I -B $AQL summary --stamps $O/aql.json $spl $twn --ranks $O/ranks.txt --ncm $O/ncm-c8t.txt --prof2 "$PROF2" --min-steps $MINST --label c8 > $O/aql-summary.txt 2>&1
  while IFS= read -r l; do xlog "${l:0:3200}"; done < <(grep -h '^AQL ' $O/aql-summary.txt 2>/dev/null)
  grep -q '^AQL c8: wall' $O/aql-summary.txt 2>/dev/null || xlog "summary: VIRHE aqlcp.py summary printed no summary line ($(tail -3 $O/aql-summary.txt 2>/dev/null | tr '\n' ' ' | cut -c1-300))"
  grep -lq '^Traceback' $O/split-*.txt $O/aql-stamps.txt $O/aql-summary.txt $O/ranks.txt $O/aql-err.txt 2>/dev/null && xlog "summary: VIRHE a Traceback in the analysis ($(grep -h -A4 '^Traceback' $O/split-*.txt $O/aql-stamps.txt $O/aql-summary.txt $O/ranks.txt $O/aql-err.txt 2>/dev/null | tail -2 | tr '\n' ' ' | cut -c1-300))"
  if [ -s $STATSDIR/stamps.csv ]; then
    if [ -s $O/aql.json ]; then gzip -1 -f $STATSDIR/stamps.csv && xlog "stamps: summarised -> $(du -m $STATSDIR/stamps.csv.gz | cut -f1) MB gz, the raw dump dropped"
    else gzip -1 -f $STATSDIR/stamps.csv && xlog "stamps: NOT summarised (no aql.json) -- kept gzipped ($(du -m $STATSDIR/stamps.csv.gz | cut -f1) MB) for a re-parse"; fi
  fi
  ( cd $O && tar -czf raw-snaps.tar.gz $(ls st-*.json fn-*.json m-*.txt c8/*-samp.jsonl c8/*-st-w*.json 2>/dev/null) 2>/dev/null \
      && rm -f st-*.json fn-*.json m-*.txt c8/*-samp.jsonl c8/*-st-w*.json ) || xlog "summary: NOTE the raw snapshots were not archived (left as they are)"
  gzip -f $O/start-*.log 2>/dev/null || true
  xlog "summary: raw snapshots -> raw-snaps.tar.gz ($(du -m $O/raw-snaps.tar.gz 2>/dev/null | cut -f1) MB); $O $(du -sm $O 2>/dev/null | cut -f1) MB; $(dfree) MB free on /"
  return 0
}
trap 'down; [ $NGB = 1 ] && [ $NGCLEAN = 0 ] && ngclean' EXIT'''
rep("trap 'down; [ $NGB = 1 ] && [ $NGCLEAN = 0 ] && ngclean' EXIT", NEWFUNCS)

# main: the start line, the selftests, the function list, the dry readings, the summary call
rep('xlog "$ITEM: start IMAGE=$IMAGE ($(docker image inspect -f \'{{.Id}}\' $IMAGE 2>/dev/null | cut -c8-19))$([ $SW = 1 ] || echo " | MOCK-RUN ZQA_SW=0 (NOT A READING): NO int9b .. int14c switch posted, cross-run references INFO") | THE int14 REFERENCE READ, ONE FRESH START on ngshare (no ATTACH), int14 pinned right after it (fn4) and read back on every rank: $DESC',
    'xlog "$ITEM: start IMAGE=$IMAGE ($(docker image inspect -f \'{{.Id}}\' $IMAGE 2>/dev/null | cut -c8-19))$([ $SW = 1 ] || echo " | MOCK-RUN ZQA_SW=0 (NOT A READING): NO int9b .. int14c switch posted, SYNTHETIC stamps") | THE AQL-STAMPED c8 CRITICAL-PATH READ (RADIANCE_AQL_STAMP=$STAMPN), ONE FRESH START on ngshare (no ATTACH), int14 pinned right after it (fn4) and read back on every rank: $DESC')
rep(' | 1 identity warm-up, a1-O vs yzint14c a1-Z + ref12 a1, gs$GSC-O, A11 in range [$A11ID], staggered (ANY failure: STOP before the speed blocks) | 2 1u essay 1 + $U1N, switched x$SWN | 3 c8 work-based gens $C8GN [$C8GORD] (B = every int14 lever at 0), c8 35 s x$C8N (INFO), c16 fixed x$C16N, c16 CAP48 | 4 cold [$CDEPTHS] | 5 c4 (warm-up $C4WARMUP) x$C4N, c1 x$C1N | budget $BUDGET min | no evict"',
    ' | the warm-up identity (STOP on a difference), $C8N STAMPED c8 blocks under O (schedule S, $C8WARM + $C8WIN s), aqlcp.py (nc $NC, >= $MINST steps) vs the unstamped twin [$TWINS] | budget $BUDGET min | no evict"')
rep('XPT=$(timeout 60 python3 -I -B $YDS selftest 2>&1 | tail -1); case "$XPT" in "SELFTEST OK"*) ;; *) HMISS="$HMISS selftest:$YDS(${XPT:0:300})" ;; esac',
    'XPT=$(timeout 60 python3 -I -B $YDS selftest 2>&1 | tail -1); case "$XPT" in "SELFTEST OK"*) ;; *) HMISS="$HMISS selftest:$YDS(${XPT:0:300})" ;; esac\n'
    'AQT=$(timeout 120 python3 -I -B $AQL selftest 2>&1 | tail -1); case "$AQT" in "SELFTEST OK"*) ;; *) HMISS="$HMISS selftest:$AQL(${AQT:0:300})" ;; esac')
rep('$YDS $NCM $NCT $DQ $SPB0 $A4TAB $A11TAB', '$YDS $NCM $NCT $DQ $SPB0 $A4TAB $A11TAB $AQL')
rep('$MBT2 $NCMB2 $C8MIX $YDS $NCM $NCT 2>&1', '$MBT2 $NCMB2 $C8MIX $YDS $NCM $NCT $AQL 2>&1')
rep('FNS="stagx coldid tabs14', 'FNS="clockpair zqreads zqsummary stagx coldid tabs14')
